# Second pass, fixing the first script (its helper was shadowed by PowerShell's own mv alias).
# Moves the Brita leftovers into additions\brita-archive-20261107 and restores the 13 gun jsons the first pass
# overwrote with markers into the archive (from the cloud copies, embedded below). Nothing is deleted.
$prof = 'C:\Users\josia\AppData\Roaming\ModrinthApp\profiles\MEDIEVAL GLOOM (1)'
$g    = Join-Path $prof 'config\zomboidcraft\guns'
$tp   = 'C:\Attachments\OneDrive\Desktop\additions\tarkov-pilot'
$arc  = 'C:\Attachments\OneDrive\Desktop\additions\brita-archive-20261107'
$log  = 'C:\Attachments\OneDrive\Desktop\additions\brita-archive-20261107-pass2.log'
'' | Set-Content $log
function L($m) { $m | Add-Content $log }
foreach ($d in 'guns','guns\poses','guns\reloads','resourcepacks') { New-Item -ItemType Directory -Force -Path (Join-Path $arc $d) | Out-Null }
function ToArchive($src, $dst) {
  if (-not (Test-Path -LiteralPath $src)) { return }
  try { Move-Item -LiteralPath $src -Destination $dst -ErrorAction Stop; L "moved $src -> $dst" }
  catch { L "FAILED $src : $($_.Exception.Message)" }
}
# undo the first pass's two stray moves
ToArchive (Join-Path $tp 'guns') (Join-Path $arc 'guns\AAC_Honey.json')
ToArchive (Join-Path $tp 'resourcepacks') (Join-Path $arc 'resourcepacks\ZomboidCraft Brita Sounds')
# the 13 overwritten gun jsons, restored into the archive
$zip = Join-Path $env:TEMP 'brita_jsons.zip'
[IO.File]::WriteAllBytes($zip, [Convert]::FromBase64String(''))
Expand-Archive -LiteralPath $zip -DestinationPath (Join-Path $arc 'guns') -Force
Remove-Item -LiteralPath $zip
L "restored jsons: $((Get-ChildItem (Join-Path $arc 'guns') -Filter *.json).Count)"
$ids = 'AAC_Honey','American180','AR57_PDW','AssaultRifle2','BOAR','Bush_AR15_MOE','Colt1911','DSHK','L86','M2Carbine','M870_CQB','RPG_7','SW_M500','TenPointTurbo_XLT','Winchester1866'
foreach ($id in $ids) {
  ToArchive (Join-Path $g "$id.zmesh") (Join-Path $arc "guns\$id.zmesh")
  ToArchive (Join-Path $g "${id}_noirons.zmesh") (Join-Path $arc "guns\${id}_noirons.zmesh")
  ToArchive (Join-Path $g "poses\$id.json") (Join-Path $arc "guns\poses\$id.json")
  ToArchive (Join-Path $g "reloads\$id.json") (Join-Path $arc "guns\reloads\$id.json")
  ToArchive (Join-Path $g "reloads\$id.cues.json") (Join-Path $arc "guns\reloads\$id.cues.json")
  $m = Get-Content -Raw -LiteralPath (Join-Path $g "$id.json")
  if ($m -notmatch '"removed":true') { L "MARKER MISSING $id" }
}
ToArchive (Join-Path $g 'parts') (Join-Path $arc 'guns\parts')
$poses = Join-Path $g 'poses'
if ((Test-Path $poses) -and -not (Get-ChildItem $poses)) { Remove-Item $poses; L 'removed empty poses folder' }
L '--- left in guns:'
Get-ChildItem -Recurse $g | ForEach-Object { L ($_.FullName.Substring($g.Length)) }
L '--- archive:'
Get-ChildItem -Recurse $arc -File | Measure-Object -Property Length -Sum | ForEach-Object { L "$($_.Count) files, $([math]::Round($_.Sum/1MB,1)) MB" }
L 'DONE'
Get-Content $log
